import importlib.util
from pathlib import Path

import pytest


def _load_typing_module():
    # Load typer/_typing.py directly from the repository tree. This avoids
    # executing typer/__init__.py, which requires click, and still exercises
    # the real source file under test.
    repo_root = Path(__file__).resolve().parent.parent
    module_path = repo_root / "typer" / "_typing.py"
    spec = importlib.util.spec_from_file_location("_typer_typing_under_test", module_path)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


@pytest.fixture(scope="module")
def typing_mod():
    return _load_typing_module()


def test_is_none_type_true_for_none(typing_mod):
    assert typing_mod.is_none_type(None) is True


def test_is_none_type_true_for_nonetype(typing_mod):
    assert typing_mod.is_none_type(typing_mod.NoneType) is True


@pytest.mark.parametrize("non_none", [int, str, float, list])
def test_is_none_type_false_for_ordinary_types(typing_mod, non_none):
    assert typing_mod.is_none_type(non_none) is False

