import types

import pytest

import fastapi._compat.v2 as v2


def test_evaluate_forwardref_uses_try_eval_type_when_available(monkeypatch):
    calls = []

    def fake_try_eval_type(value, globalns, localns):
        calls.append(("try_eval_type", value))
        return ("resolved", None)

    def fake_eval_type_lenient(value, globalns, localns):
        raise AssertionError("eval_type_lenient must not be used when try_eval_type exists")

    fake_module = types.SimpleNamespace(
        try_eval_type=fake_try_eval_type,
        eval_type_lenient=fake_eval_type_lenient,
    )
    monkeypatch.setattr(v2, "_pydantic_typing_extra", fake_module)

    result = v2.evaluate_forwardref("SomeType")

    assert result == "resolved"
    assert calls == [("try_eval_type", "SomeType")]


def test_evaluate_forwardref_falls_back_to_eval_type_lenient(monkeypatch):
    def fake_eval_type_lenient(value, globalns, localns):
        return ("legacy", value)

    fake_module = types.SimpleNamespace(
        try_eval_type=None,
        eval_type_lenient=fake_eval_type_lenient,
    )
    monkeypatch.setattr(v2, "_pydantic_typing_extra", fake_module)

    result = v2.evaluate_forwardref("SomeType")

    assert result == ("legacy", "SomeType")

