import inspect

from click.types import FuncParamType


def _return_annotation_name(func):
    ann = inspect.signature(func).return_annotation
    if isinstance(ann, str):
        return ann
    return getattr(ann, "__name__", repr(ann))


def test_func_param_type_convert_returns_type_variable_annotation():
    # Fails when the return annotation is changed to None; passes with ParamTypeValue.
    assert _return_annotation_name(FuncParamType.convert) == "ParamTypeValue"


def test_func_param_type_convert_returns_func_result(tmp_path):
    # Behavioral sanity check: conversion delegates to the wrapped function.
    param_type = FuncParamType(int)
    assert param_type.convert("3", None, None) == 3

from pydantic import BaseModel
from pydantic._internal._generics import (
    get_cached_generic_type_early,
    set_cached_generic_type,
)


class _Parent(BaseModel):
    pass


class _Child(BaseModel):
    pass


def test_early_cache_lookup_returns_previously_cached_type():
    # Populate the cache through the public setter, then read it back
    # through the early lookup. The cached type must be returned.
    set_cached_generic_type(_Parent, (int,), _Child)

    assert get_cached_generic_type_early(_Parent, (int,)) is _Child


def test_early_cache_lookup_misses_for_uncached_arguments():
    # A lookup for arguments that were never cached must return None.
    # Guards against a fix that returns a stale or unrelated type.
    assert get_cached_generic_type_early(_Parent, (str,)) is None

from typing import Annotated

from pydantic import ConfigDict, Field, ValidationError, validate_call


def test_validate_call_accepts_field_name_when_validate_by_name_is_set():
    @validate_call(config=ConfigDict(validate_by_name=True, validate_by_alias=True))
    def f(x: Annotated[int, Field(alias='y')]) -> int:
        return x

    assert f(x=1) == 1


def test_validate_call_accepts_alias_when_validate_by_alias_is_set():
    @validate_call(config=ConfigDict(validate_by_name=True, validate_by_alias=True))
    def f(x: Annotated[int, Field(alias='y')]) -> int:
        return x

    assert f(y=2) == 2


def test_validate_call_rejects_field_name_when_validate_by_name_is_unset():
    @validate_call(config=ConfigDict(validate_by_alias=True, validate_by_name=False))
    def f(x: Annotated[int, Field(alias='y')]) -> int:
        return x

    try:
        f(x=1)
    except ValidationError:
        pass
    else:
        raise AssertionError('expected ValidationError when calling by field name without validate_by_name')
